// output the byte when a stop bit is received. The done signal is asserted
// each time a byte is received.
module TopModule (
    input  clk,
    input  in,
    input  reset,
    output reg [7:0] out_byte,
    output reg done
);
    reg [2:0] state;
    reg [7:0] shiftreg;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            shiftreg <= 0;
            done <= 0;
