                    shiftreg <= {in, shiftreg[7:1]};
                    if (&state) state <= 2;
                    else state <= state + 1;
                end
                2: begin // Wait for stop bit
                    if (in == 1) begin
                        out_byte <= shiftreg;
                        done <= 1;
                    end
                    state <= 0;
                end
            endcase
        end
    end
endmodule

