// with start/stop bits. The byte is valid on the positive edge of done
// when the stop bit is seen.
module TopModule(input clk, input in, input reset, output reg [7:0] out_byte, output reg done);
    reg [2:0] state;
    reg [7:0] byte;
    reg [2:0] bit_count;
    always @(posedge clk) begin
        if (reset) begin
            state <= 0;
            byte <= 0;
            bit_count <= 0;
            done <= 0;
            out_byte <= 0;
        end else begin
            case (state)
                0: begin // Wait for start bit
                    if (in == 0) begin
                        state <= 1;
                        bit_count <= 0;
                    end
                end
                1: begin // Wait for data bit 0
                    if (in == byte[0]) begin
                        byte <= {byte[6:0], in};
                        bit_count <= bit_count + 1;
                        if (bit_count == 7) state <= 2;
                    end
                end
                2: begin // Wait for data bit 1
                    if (in == byte[1]) begin
                        byte <= {byte[6:0], in};
                        bit_count <= bit_count + 1;
                        if (bit_count == 8) state <= 3;
                    end
                end
                3: begin // Wait for data bit 2
                    if (in == byte[2]) begin
                        byte <= {byte[6:0], in};
                        bit_count <= bit_count + 1;
                        if (bit_count == 9) state <= 4;
                    end
                end
                4: begin // Wait for data bit 3
                    if (in == byte[3]) begin
                        byte <= {byte[6:0], in};
                        bit_count <= bit_count + 1;
                        if (bit_count == 10) state <= 5;
                    end
                end
                5: begin // Wait for data bit 4
                    if (in == byte[4]) begin
                        byte <= {byte[6:0], in};
                        bit_count <= bit_count + 1;
                        if (bit_count == 11) state <= 6;
                    end
                end
                6: begin // Wait for data bit 5
                    if (in == byte[5]) begin
                        byte <= {byte[6:0], in};
                        bit_count <= bit_count + 1;
                        if (bit_count == 12) state <= 7;
                    end
                end
                7: begin // Wait for data bit 6
