// One-bit synchronous reset, one-bit register, one-bit multiplexer,
// one-bit counter -> combinational multiplexer on the next stage ->
// combinational register -> FSM. The register stage breaks the path
// from the input to the FSM, increasing the frequency at which the FSM
// can be clocked independently of the input.
module TopModule(input clk, input in, input reset, output [7:0] out_byte, output reg done);
  reg [7:0] byte;
  reg [2:0] stage;
  reg [2:0] count;
  reg start;
  reg [7:0] data;
  reg stop;
  always @(posedge clk) begin
    if (reset) begin
      stage <= 0;
      count <= 0;
      start <= 0;
      stop <= 0;
      done <= 0;
    end else begin
      case (stage)
        0: begin
          if (in == 1'b0) begin
            stage <= 1;
            count <= 0;
          end
        end
        1: begin
          if (count == 7) begin
            stage <= 2;
          end else begin
            count <= count + 1;
          end
        end
        2: begin
          if (in == 1'b1) begin
            stop <= 1;
            stage <= 3;
          end
        end
        3: begin
          if (in == 1'b0) begin
            byte <= data;
            done <= 1;
            stage <= 0;
          end
        end
      endcase
    end
  end
  always @(posedge clk) data[0] = in;
  always @(posedge clk) data[1] = in;
  always @(posedge clk) data[2] = in;
  always @(posedge clk) data[3] = in;
  always @(posedge clk) data[4] = in;
  always @(posedge clk) data[5] = in;
  always @(posedge clk) data[6] = in;
  always @(posedge clk) data[7] = in;
  assign out_byte = byte;
endmodule

